"""Database abstractions to decouple plugins and services from concrete implementations."""

from abc import ABC, abstractmethod
from typing import Optional, List, Dict, Any, Iterable
from pyrogram.types import Message as PyroMessage


class IMediaRepository(ABC):
    """Repository interface for media/file search and storage."""

    @abstractmethod
    async def save_file(self, media: Any) -> tuple:
        """Save a media file. Returns (success: bool, code: int)"""
        pass

    @abstractmethod
    async def get_file_details(self, file_id: str) -> Optional[List[Dict]]:
        """Get file details by file_id."""
        pass

    @abstractmethod
    async def get_search_results(
        self,
        query: str,
        file_type: Optional[str] = None,
        max_results: int = 10,
        offset: int = 0,
        filter: bool = True
    ) -> tuple:
        """Return (files: List, next_offset: int, total: int)."""
        pass


class IUserRepository(ABC):
    """Repository interface for user management."""

    @abstractmethod
    async def add_user(self, user_id: int, name: str):
        pass

    @abstractmethod
    async def is_user_exist(self, user_id: int) -> bool:
        pass

    @abstractmethod
    async def total_users_count(self) -> int:
        pass

    @abstractmethod
    async def ban_user(self, user_id: int, ban_reason: str = "No Reason"):
        pass

    @abstractmethod
    async def remove_ban(self, user_id: int):
        pass

    @abstractmethod
    async def get_ban_status(self, user_id: int) -> Dict:
        pass

    @abstractmethod
    async def get_all_users(self) -> Iterable[Dict]:
        pass

    @abstractmethod
    async def delete_user(self, user_id: int):
        pass

    @abstractmethod
    async def get_banned(self) -> tuple:
        """Return (banned_user_ids: List, banned_chat_ids: List)."""
        pass


class IGroupRepository(ABC):
    """Repository interface for group/chat management."""

    @abstractmethod
    async def add_chat(self, chat_id: int, title: str):
        pass

    @abstractmethod
    async def get_chat(self, chat_id: int) -> Optional[Dict]:
        pass

    @abstractmethod
    async def disable_chat(self, chat_id: int, reason: str = "No Reason"):
        pass

    @abstractmethod
    async def re_enable_chat(self, chat_id: int):
        pass

    @abstractmethod
    async def get_all_chats(self) -> Iterable[Dict]:
        pass

    @abstractmethod
    async def total_chat_count(self) -> int:
        pass

    @abstractmethod
    async def update_settings(self, chat_id: int, settings: Dict):
        pass

    @abstractmethod
    async def get_settings(self, chat_id: int) -> Dict:
        pass


class IConnectionRepository(ABC):
    """Repository interface for user-group connections."""

    @abstractmethod
    async def add_connection(self, group_id: int, user_id: int) -> bool:
        pass

    @abstractmethod
    async def active_connection(self, user_id: int) -> Optional[int]:
        pass

    @abstractmethod
    async def all_connections(self, user_id: int) -> Optional[List[int]]:
        pass

    @abstractmethod
    async def if_active(self, user_id: int, group_id: int) -> bool:
        pass

    @abstractmethod
    async def make_active(self, user_id: int, group_id: int) -> bool:
        pass

    @abstractmethod
    async def make_inactive(self, user_id: int) -> bool:
        pass

    @abstractmethod
    async def delete_connection(self, user_id: int, group_id: int) -> bool:
        pass


class IFilterRepository(ABC):
    """Repository interface for group filters."""

    @abstractmethod
    async def add_filter(self, group_id: int, text: str, reply_text: str, btn: str, file: str, alert: str):
        pass

    @abstractmethod
    async def find_filter(self, group_id: int, name: str) -> tuple:
        """Return (reply_text, btn, alert, fileid)."""
        pass

    @abstractmethod
    async def get_filters(self, group_id: int) -> List[str]:
        pass

    @abstractmethod
    async def delete_filter(self, group_id: int, text: str):
        pass

    @abstractmethod
    async def del_all_filters(self, group_id: int):
        pass

    @abstractmethod
    async def count_filters(self, group_id: int) -> int:
        pass

    @abstractmethod
    async def filter_stats(self) -> tuple:
        """Return (total_collections: int, totalcount: int)."""
        pass
